-- Explicações por artigo — Lei de Interceptação Telefônica (Lei nº 9.296, de 1996). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A interceptação de comunicações telefônicas, de qualquer natureza, para prova em investigação criminal e em instrução processual penal, observará esta Lei e dependerá de ordem do juiz competente da ação principal, sob segredo de justiça. O disposto na Lei aplica-se à interceptação do fluxo de comunicações em sistemas de informática e telemática.', '["Interceptação telefônica depende de ordem do juiz competente da ação principal.","Segredo de justiça.","Serve de prova em investigação criminal e instrução processual penal.","Aplica-se ao fluxo de comunicações em informática e telemática."]'::jsonb, '["Cláusula de reserva de jurisdição: só o juiz autoriza (Constituição, art. 5º, XII).","Não se aplica a processos cíveis."]'::jsonb, 'A Polícia Federal só grampeia um telefone com ordem do juiz.', '["Assertiva que permite ao delegado ou ao Ministério Público determinar a interceptação erra: depende de ordem judicial."]'::jsonb, '[{"termo":"Interceptação","significado":"Captação da comunicação por terceiro, sem o conhecimento dos interlocutores."}]'::jsonb, '["Art. 2º","Art. 10"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'interceptacao' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não será admitida a interceptação de comunicações telefônicas quando não houver indícios razoáveis da autoria ou participação em infração penal; quando a prova puder ser feita por outros meios disponíveis; ou quando o fato investigado constituir infração penal punida, no máximo, com pena de detenção. Em qualquer hipótese deve ser descrita com clareza a situação objeto da investigação, inclusive com a indicação e qualificação dos investigados, salvo impossibilidade manifesta, devidamente justificada.', '["Vedada sem indícios razoáveis de autoria ou participação.","Vedada se a prova puder ser feita por outros meios (subsidiariedade).","Vedada para crime punido apenas com detenção.","Descrição clara da situação e qualificação dos investigados."]'::jsonb, '["Só cabe para crimes punidos com RECLUSÃO.","Subsidiariedade: é o último recurso."]'::jsonb, 'Contravenção ou crime punido só com detenção não permite interceptação.', '["Assertiva que admite a interceptação para crime punido apenas com detenção erra."]'::jsonb, '[{"termo":"Subsidiariedade","significado":"A medida só cabe se não houver outro meio de prova."}]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'interceptacao' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A interceptação das comunicações telefônicas poderá ser determinada pelo juiz, de ofício ou a requerimento da autoridade policial, na investigação criminal, ou do representante do Ministério Público, na investigação criminal e na instrução processual penal.', '["Juiz pode determinar de ofício.","Autoridade policial requer na investigação criminal.","Ministério Público requer na investigação e na instrução."]'::jsonb, '["A autoridade policial NÃO pede na fase processual; o MP pede nas duas fases."]'::jsonb, 'O delegado representa pela interceptação durante o inquérito.', '["Assertiva que permite ao delegado requerer a interceptação na instrução processual erra: lá só o MP requer."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'interceptacao' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O pedido de interceptação conterá a demonstração de que a sua realização é necessária à apuração de infração penal, com indicação dos meios a serem empregados. Excepcionalmente, o juiz poderá admitir que o pedido seja formulado verbalmente, desde que presentes os pressupostos que autorizem a interceptação, caso em que a concessão será condicionada à sua redução a termo. O juiz, no prazo máximo de vinte e quatro horas, decidirá sobre o pedido.', '["Pedido demonstra necessidade e indica os meios.","Pedido verbal em caráter excepcional, reduzido a termo.","Decisão do juiz em até vinte e quatro horas."]'::jsonb, '["Prazo curto para o juiz decidir: vinte e quatro horas."]'::jsonb, 'Em caso excepcional, o pedido feito de forma verbal é reduzido a termo.', '["Assertiva que fixa em dois dias o prazo para decidir erra: são vinte e quatro horas."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'interceptacao' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A decisão será fundamentada, sob pena de nulidade, indicando também a forma de execução da diligência, que não poderá exceder o prazo de quinze dias, renovável por igual tempo uma vez comprovada a indispensabilidade do meio de prova.', '["Decisão fundamentada, sob pena de nulidade.","Indica a forma de execução.","Prazo de quinze dias, renovável por igual tempo."]'::jsonb, '["Jurisprudência admite renovações sucessivas, desde que fundamentadas e comprovada a indispensabilidade.","Prazo inicial de quinze dias."]'::jsonb, 'O juiz autoriza por quinze dias e renova, com fundamentação, por mais quinze.', '["Assertiva que fixa em um mês o prazo inicial erra: são quinze dias."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'interceptacao' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deferido o pedido, a autoridade policial conduzirá os procedimentos de interceptação, dando ciência ao Ministério Público, que poderá acompanhar a sua realização. Havendo gravação, será determinada a sua transcrição. Cumprida a diligência, a autoridade policial encaminhará o resultado ao juiz, com auto circunstanciado contendo o resumo das operações realizadas. Recebidos esses elementos, o juiz determinará a providência do art. 8º, ciente o Ministério Público.', '["Autoridade policial conduz os procedimentos.","Ciência ao Ministério Público, que pode acompanhar.","Transcrição das gravações.","Auto circunstanciado ao juiz."]'::jsonb, '["A interceptação é conduzida pela POLÍCIA, com ciência ao MP.","Há discussão jurisprudencial sobre a necessidade de transcrição integral."]'::jsonb, 'A polícia envia ao juiz as gravações e o auto circunstanciado ao fim da diligência.', '["Assertiva que atribui ao Ministério Público a condução da interceptação erra: é da autoridade policial."]'::jsonb, '[{"termo":"Auto circunstanciado","significado":"Documento que resume as operações realizadas."}]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'interceptacao' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para os procedimentos de interceptação, a autoridade policial poderá requisitar serviços e técnicos especializados às concessionárias de serviço público.', '["Requisição de serviços e técnicos às concessionárias de serviço público."]'::jsonb, '["A operadora atua apenas na execução técnica."]'::jsonb, 'A polícia requisita à operadora de telefonia o desvio das chamadas.', '["Assertiva que torna a requisição à operadora dependente de nova ordem a cada ligação erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'interceptacao' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A interceptação de comunicação telefônica ocorrerá em autos apartados, apensados aos autos do inquérito policial ou do processo criminal, preservando-se o sigilo das diligências, gravações e transcrições. A apensação somente poderá ser realizada imediatamente antes do relatório da autoridade, no inquérito, ou na conclusão do processo ao juiz para o despacho dos arts. 407, 502 ou 538 do Código de Processo Penal.', '["Autos apartados, apensados ao inquérito ou processo.","Sigilo das diligências, gravações e transcrições.","Apensação só antes do relatório do delegado ou na conclusão ao juiz."]'::jsonb, '["Sigilo é a regra; a apensação é tardia."]'::jsonb, 'As gravações ficam em autos separados e sigilosos até a apensação.', '["Assertiva que permite juntar as gravações ao inquérito desde o início erra: a apensação é tardia."]'::jsonb, '[{"termo":"Apensar","significado":"Juntar autos para que tramitem em conjunto."}]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'interceptacao' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para investigação ou instrução criminal, o juiz poderá autorizar, a requerimento da autoridade policial ou do Ministério Público, a captação ambiental de sinais eletromagnéticos, ópticos ou acústicos, quando a prova não puder ser feita por outros meios igualmente eficazes e houver elementos probatórios razoáveis de autoria e participação em infrações cujas penas máximas sejam superiores a 4 anos ou em infrações conexas. O requerimento descreve o local e a forma de instalação do dispositivo. A instalação pode ocorrer por operação policial disfarçada ou no período noturno, exceto na casa. O prazo não pode exceder quinze dias, renovável por iguais períodos, se comprovada a indispensabilidade e presente atividade criminal permanente, habitual ou continuada. A captação feita por um dos interlocutores sem prévio conhecimento da autoridade poderá ser usada em matéria de defesa, se demonstrada a integridade da gravação. Aplicam-se subsidiariamente as regras da interceptação telefônica e telemática.', '["Captação ambiental com autorização judicial, a requerimento da polícia ou do MP.","Subsidiariedade e elementos razoáveis de autoria.","Infrações com pena máxima superior a 4 anos ou conexas.","Instalação por operação disfarçada ou à noite, exceto em casa.","Prazo de quinze dias, renovável.","Gravação de um dos interlocutores pode ser usada pela defesa."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.964, de 2019 (Pacote Anticrime).","Limite: pena máxima SUPERIOR a 4 anos.","Em casa, a instalação não pode ser feita à noite."]'::jsonb, 'Com autorização judicial, a polícia instala um microfone em um veículo usado pela organização criminosa.', '["Assertiva que permite instalar o dispositivo de captação no período noturno dentro da casa erra: a ressalva é a inviolabilidade do domicílio."]'::jsonb, '[{"termo":"Captação ambiental","significado":"Gravação de sons e imagens do ambiente."}]'::jsonb, '["Art. 10-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'interceptacao' and u.unit_key = 'art-8-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A gravação que não interessar à prova será inutilizada por decisão judicial, durante o inquérito, a instrução processual ou após esta, em virtude de requerimento do Ministério Público ou da parte interessada. O incidente de inutilização será assistido pelo Ministério Público, sendo facultada a presença do acusado ou de seu representante legal.', '["Gravação irrelevante é inutilizada por decisão judicial.","A pedido do MP ou da parte interessada.","Assistido pelo Ministério Público, com presença facultada ao acusado."]'::jsonb, '["Protege a intimidade de terceiros."]'::jsonb, 'Conversas pessoais sem relação com o crime são destruídas por decisão judicial.', '["Assertiva que permite à polícia inutilizar as gravações por conta própria erra: exige decisão judicial."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'interceptacao' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constitui crime realizar interceptação de comunicações telefônicas, de informática ou telemática, promover escuta ambiental ou quebrar segredo da Justiça, sem autorização judicial ou com objetivos não autorizados em lei. Pena: reclusão de dois a quatro anos e multa. Incorre na mesma pena a autoridade judicial que determina a execução dessa conduta com objetivo não autorizado em lei.', '["Interceptação, escuta ambiental ou quebra de segredo de justiça sem autorização ou com objetivo ilegal.","Reclusão de dois a quatro anos e multa.","Juiz que determina a conduta com objetivo ilegal responde igualmente."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 13.869, de 2019 (Lei de Abuso de Autoridade).","O próprio juiz pode ser sujeito ativo."]'::jsonb, 'Policial que grampeia telefone sem ordem judicial pratica o crime.', '["Assertiva que isenta o juiz que determina a medida com objetivo ilegal erra: ele incorre na mesma pena."]'::jsonb, '[]'::jsonb, '["Art. 10-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'interceptacao' and u.unit_key = 'art-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Realizar captação ambiental de sinais eletromagnéticos, ópticos ou acústicos para investigação ou instrução criminal sem autorização judicial, quando esta for exigida: reclusão de dois a quatro anos e multa. Não há crime se a captação é realizada por um dos interlocutores. A pena será aplicada em dobro ao funcionário público que descumprir determinação de sigilo das investigações que envolvam a captação ambiental ou revelar o conteúdo das gravações enquanto mantido o sigilo judicial.', '["Captação ambiental sem autorização judicial: dois a quatro anos e multa.","Atípica se feita por um dos interlocutores.","Pena em dobro ao funcionário que violar o sigilo."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.964, de 2019.","Gravação por um dos interlocutores não é crime."]'::jsonb, 'Quem grava a própria conversa não comete o crime, ainda que sem autorização.', '["Assertiva que tipifica a gravação feita por um dos interlocutores erra: o §1º afasta o crime."]'::jsonb, '[]'::jsonb, '["Art. 8º-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'interceptacao' and u.unit_key = 'art-10-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

